//! Player scores shared between the match threads of the Pixel Arena server.

use std::collections::HashMap;
use std::sync::{Arc, Mutex, MutexGuard};

pub type PlayerId = u32;

#[derive(Default)]
struct Scores {
    players: HashMap<PlayerId, i64>,
    total: i64,
}

/// Clones share the same scores, so each match thread keeps its own handle.
///
/// Every operation takes the single state lock, so a score and the board total
/// are always updated together and lock order can never invert.
#[derive(Clone, Default)]
pub struct Board {
    scores: Arc<Mutex<Scores>>,
}

impl Board {
    pub fn new() -> Self {
        Self::default()
    }

    fn lock(&self) -> MutexGuard<'_, Scores> {
        // A panic elsewhere must not make the shared board unusable.
        self.scores
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
    }

    pub fn join(&self, id: PlayerId, score: i64) {
        let mut scores = self.lock();
        let previous = scores.players.insert(id, score);
        // A repeated join replaces the old score and keeps total == sum(scores).
        scores.total += score - previous.unwrap_or(0);
    }

    /// Adds points to a player and to the board total.
    pub fn award(&self, id: PlayerId, points: i64) {
        let mut scores = self.lock();
        let slot = scores
            .players
            .get_mut(&id)
            .unwrap_or_else(|| panic!("award for unknown player {id}"));
        *slot += points;
        scores.total += points;
    }

    /// Moves points between two players. The board total does not change.
    /// Moving points from a player to the same player changes nothing.
    pub fn transfer(&self, from: PlayerId, to: PlayerId, points: i64) {
        let mut scores = self.lock();
        if !scores.players.contains_key(&from) {
            panic!("transfer from unknown player {from}");
        }
        if !scores.players.contains_key(&to) {
            panic!("transfer to unknown player {to}");
        }
        if from == to {
            return;
        }

        *scores.players.get_mut(&from).unwrap() -= points;
        *scores.players.get_mut(&to).unwrap() += points;
    }

    pub fn score(&self, id: PlayerId) -> i64 {
        *self
            .lock()
            .players
            .get(&id)
            .unwrap_or_else(|| panic!("score for unknown player {id}"))
    }

    pub fn total(&self) -> i64 {
        self.lock().total
    }
}

